/* Return NULL if failed */
/* Assume symmetry is transformed in primitive cell. */
Spacegroup *spa_search_spacegroup_with_symmetry(Symmetry const *symmetry,
                                                double const prim_lat[3][3],
                                                double const symprec) {
    int i;
    Spacegroup *spacegroup;
    Primitive *primitive;
    Symmetry *red_symmetry;
    double red_lattice[3][3];

    spacegroup = NULL;
    primitive = NULL;
    red_symmetry = NULL;

    /* The space-group type is a property of the crystal and not of the basis */
    /* in which the operations are written. The point-group search assumes a */
    /* reduced primitive basis because the symmetry axes are looked for among */
    /* low index directions. Any other primitive basis of the same lattice is */
    /* equally valid as an input, therefore the basis is reduced here and the */
    /* operations are transformed coherently into it, i.e., the lattice and */
    /* the operations keep describing the same crystal. */
    red_symmetry =
        get_symmetry_in_reduced_basis(red_lattice, prim_lat, symmetry, symprec);

    if ((primitive = prm_alloc_primitive(1)) == NULL) {
        goto ret;
    }
    if ((primitive->cell = cel_alloc_cell(1, NOSPIN)) == NULL) {
        goto ret;
    }
    for (i = 0; i < 3; i++) {
        primitive->cell->position[0][i] = 0;
    }

    if (red_symmetry != NULL) {
        mat_copy_matrix_d3(primitive->cell->lattice, red_lattice);
        spacegroup = search_spacegroup_with_symmetry(
            primitive, spacegroup_to_hall_number, 230, red_symmetry, symprec,
            -1.0);
    }

    /* Fall back to the basis as given when it could not be reduced or when */
    /* no space-group type was found in the reduced basis. */
    if (spacegroup == NULL) {
        mat_copy_matrix_d3(primitive->cell->lattice, prim_lat);
        spacegroup = search_spacegroup_with_symmetry(
            primitive, spacegroup_to_hall_number, 230, symmetry, symprec, -1.0);
    }

ret:
    if (red_symmetry != NULL) {
        sym_free_symmetry(red_symmetry);
        red_symmetry = NULL;
    }
    if (primitive != NULL) {
        prm_free_primitive(primitive);
        primitive = NULL;
    }

    return spacegroup;
}

/* Metric tensor of the lattice symmetrized over the rotation parts of the */
/* given operations: G = (1/N) sum_R R^T G_lattice R. G is invariant under */
/* the operations by construction, so it is the metric tensor of a lattice */
/* whose point group contains them. */
static void get_invariant_metric(double metric[3][3],
                                 double const lattice[3][3],
                                 Symmetry const *symmetry) {
    int i, j, k;
    double lattice_metric[3][3], rot_d3[3][3], tmp_mat[3][3];
    PointSymmetry pointsym;

    mat_transpose_matrix_d3(tmp_mat, lattice);
    mat_multiply_matrix_d3(lattice_metric, tmp_mat, lattice);

    /* Rotations have to be counted once each to make G invariant. */
    pointsym = ptg_get_pointsymmetry(symmetry->rot, symmetry->size);

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            metric[i][j] = 0;
        }
    }

    for (k = 0; k < pointsym.size; k++) {
        mat_cast_matrix_3i_to_3d(rot_d3, pointsym.rot[k]);
        mat_transpose_matrix_d3(tmp_mat, rot_d3);
        mat_multiply_matrix_d3(tmp_mat, tmp_mat, lattice_metric);
        mat_multiply_matrix_d3(tmp_mat, tmp_mat, rot_d3);
        for (i = 0; i < 3; i++) {
            for (j = 0; j < 3; j++) {
                metric[i][j] += tmp_mat[i][j] / pointsym.size;
            }
        }
    }
}

/* Cholesky decomposition G = B^T B. Column vectors of the upper triangular */
/* matrix B are basis vectors having the metric tensor G. Return 0 if the */
/* metric tensor is not positive definite. */
static int get_basis_from_metric(double basis[3][3],
                                 double const metric[3][3]) {
    int i, j;
    double sum;

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            basis[i][j] = 0;
        }
    }

    for (j = 0; j < 3; j++) {
        sum = metric[j][j];
        for (i = 0; i < j; i++) {
            sum -= basis[i][j] * basis[i][j];
        }
        if (sum < ZERO_PREC) {
            return 0;
        }
        basis[j][j] = sqrt(sum);
        for (i = j + 1; i < 3; i++) {
            sum = metric[j][i];
            for (int k = 0; k < j; k++) {
                sum -= basis[k][j] * basis[k][i];
            }
            basis[j][i] = sum / basis[j][j];
        }
    }

    return 1;
}

/* Change of basis matrix P with (a_red, b_red, c_red) = (a, b, c) P that */
/* makes the basis reduced with respect to the symmetrized metric tensor. */
/* P is unimodular, i.e., the lattice is unchanged. Return 0 if failed. */
static int get_reducing_change_of_basis(int tmat_int[3][3],
                                        double const lattice[3][3],
                                        Symmetry const *symmetry,
                                        double const symprec) {
    double metric[3][3], basis[3][3], red_basis[3][3];
    double inv_basis[3][3], tmat[3][3];

    get_invariant_metric(metric, lattice, symmetry);
    if (!get_basis_from_metric(basis, metric)) {
        return 0;
    }
    if (!del_delaunay_reduce(red_basis, basis, symprec)) {
        return 0;
    }
    if (!mat_inverse_matrix_d3(inv_basis, basis, symprec)) {
        return 0;
    }
    mat_multiply_matrix_d3(tmat, inv_basis, red_basis);
    mat_cast_matrix_3d_to_3i(tmat_int, tmat);
    /* The change of basis of a lattice is integral and unimodular. */
    if (!mat_check_identity_matrix_id3(tmat_int, tmat, INT_PREC)) {
        return 0;
    }
    if (abs(mat_get_determinant_i3(tmat_int)) != 1) {
        return 0;
    }

    return 1;
}

/* Rewrite lattice and operations in a reduced basis of the same lattice: */
/* (a_red, b_red, c_red) = (a, b, c) P, R_red = P^-1 R P, t_red = P^-1 t. */
/* Return NULL if failed, then the given basis has to be used as it is. */
static Symmetry *get_symmetry_in_reduced_basis(double red_lattice[3][3],
                                               double const prim_lat[3][3],
                                               Symmetry const *symmetry,
                                               double const symprec) {
    int i, j;
    int tmat_int[3][3];
    double tmat[3][3], inv_tmat[3][3], rot_d3[3][3];
    Symmetry *red_symmetry;

    red_symmetry = NULL;

    if (!get_reducing_change_of_basis(tmat_int, prim_lat, symmetry, symprec)) {
        return NULL;
    }

    mat_cast_matrix_3i_to_3d(tmat, tmat_int);
    if (!mat_inverse_matrix_d3(inv_tmat, tmat, 0)) {
        return NULL;
    }
    /* The lattice follows the same change of basis as the operations. */
    mat_multiply_matrix_d3(red_lattice, prim_lat, tmat);

    if ((red_symmetry = sym_alloc_symmetry(symmetry->size)) == NULL) {
        return NULL;
    }

    for (i = 0; i < symmetry->size; i++) {
        mat_cast_matrix_3i_to_3d(rot_d3, symmetry->rot[i]);
        /* P^-1 R P */
        mat_get_similar_matrix_d3(rot_d3, rot_d3, tmat, 0);
        mat_cast_matrix_3d_to_3i(red_symmetry->rot[i], rot_d3);
        mat_multiply_matrix_vector_d3(red_symmetry->trans[i], inv_tmat,
                                      symmetry->trans[i]);
        for (j = 0; j < 3; j++) {
            red_symmetry->trans[i][j] = mat_Dmod1(red_symmetry->trans[i][j]);
        }
    }

    return red_symmetry;
}

